<｜｜DSML｜｜invoke name="execute_bash">
<｜｜DSML｜｜parameter name="command">
grep -rn "offsetToIndex\|struct ExtendedTypes\|struct Types" /workspace/repo-vul/src-vul/harfbuzz/src/hb-aat-layout-common.hh /workspace/repo-vul/src-vul/harfbuzz/src/hb-aat-layout.hh 2>/dev/null | head -40
</｜｜DSML｜｜parameter>
</｜｜DSML｜｜invoke>
